        public static TheoryModule ModuleById(string id) => MODULES.FirstOrDefault(m => m.id == id);
        public static ExamDef ExamById(string id) => EXAMS.FirstOrDefault(e => e.id == id);

        /// <summary>Deterministic question selection for an exam attempt (seeded so results are reproducible in tests).</summary>
        public static List<Question> ExamQuestions(ExamDef exam, long attemptSeed)
        {
            var pool = exam.modules.SelectMany(m => ModuleById(m)?.quiz ?? new Question[0]).ToList();
            uint s = unchecked((uint)(attemptSeed * 2654435761L));
            if (s == 0) s = 1;
            double Rnd() { s ^= s << 13; s ^= s >> 17; s ^= s << 5; return s / 4294967296.0; }
            for (int i = pool.Count - 1; i > 0; i--) { var j = (int)Math.Floor(Rnd() * (i + 1)); (pool[i], pool[j]) = (pool[j], pool[i]); }
            return pool.Take(Math.Min(exam.questionCount, pool.Count)).ToList();
        }

        /// <summary>Grade answers: percentage and per-question correctness.</summary>
        public static (int pct, bool[] correct) GradeAnswers(IList<Question> questions, IList<int?> answers)
        {
            var correct = questions.Select((q, i) => i < answers.Count && answers[i] == q.answer).ToArray();
            var pct = questions.Count > 0 ? (int)Math.Round(correct.Count(c => c) * 100.0 / questions.Count, MidpointRounding.AwayFromZero) : 0;
            return (pct, correct);
        }
    }
